package com.anthony6996.hardcorecompass.manager;

import com.anthony6996.hardcorecompass.HardcoreCompassPlugin;
import com.anthony6996.hardcorecompass.config.ConfigManager;
import com.anthony6996.hardcorecompass.storage.LodestoneStorage;
import org.bukkit.Bukkit;import org.bukkit.Location;import org.bukkit.Material;import org.bukkit.NamespacedKey;import org.bukkit.Sound;import org.bukkit.World;import org.bukkit.block.Block;import org.bukkit.entity.Player;import org.bukkit.inventory.ItemStack;import org.bukkit.inventory.Recipe;import org.bukkit.inventory.ShapedRecipe;import org.bukkit.inventory.meta.CompassMeta;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.PersistentDataType;
import java.util.List;import java.util.UUID;
public final class CompassManager {
 private final HardcoreCompassPlugin plugin;private final NamespacedKey compassKey,lodestoneKey,compassRecipeKey,lodestoneRecipeKey,targetLabelKey;private final ConfigManager config;private final LodestoneStorage lodestones;
 public CompassManager(HardcoreCompassPlugin p,ConfigManager c,LodestoneStorage storage){plugin=p;config=c;lodestones=storage;compassKey=new NamespacedKey(p,"hardcore_compass");lodestoneKey=new NamespacedKey(p,"hardcore_lodestone");targetLabelKey=new NamespacedKey(p,"target_label");compassRecipeKey=new NamespacedKey(p,"hardcore_compass_recipe");lodestoneRecipeKey=new NamespacedKey(p,"hardcore_lodestone_recipe");}
 public void registerRecipe(){Bukkit.removeRecipe(compassRecipeKey);Bukkit.removeRecipe(lodestoneRecipeKey);if(config.recipeEnabled())registerConfigured("compass",compassRecipeKey,createCompass(null,null));if(config.lodestoneRecipeEnabled())registerConfigured("lodestone",lodestoneRecipeKey,createLodestone(null));}
 private void registerConfigured(String section,NamespacedKey key,ItemStack result){try{List<String> shape=config.recipeShape(section);java.util.Set<Character> symbols=new java.util.HashSet<>();if(shape.isEmpty()||shape.size()>3)throw new IllegalArgumentException("shape must contain 1-3 rows");for(String row:shape){if(row==null||row.isEmpty()||row.length()>3)throw new IllegalArgumentException("each shape row must contain 1-3 characters");row.chars().filter(ch->ch!=' ').forEach(ch->symbols.add((char)ch));}if(symbols.isEmpty())throw new IllegalArgumentException("shape must use ingredient symbols");ShapedRecipe r=new ShapedRecipe(key,result);r.shape(shape.toArray(String[]::new));for(char symbol:symbols){Material m=config.recipeIngredient(section,symbol);if(m==null)throw new IllegalArgumentException("invalid/missing material for symbol "+symbol);r.setIngredient(symbol,m);}if(!Bukkit.addRecipe(r))throw new IllegalStateException("Bukkit rejected recipe registration");}catch(RuntimeException ex){plugin.getLogger().severe("Disabled invalid recipe.recipe."+section+": "+ex.getMessage()+". Plugin will continue enabling.");}}
 public boolean isCompassRecipe(Recipe r){return r instanceof ShapedRecipe s&&compassRecipeKey.equals(s.getKey());}public boolean isLodestoneRecipe(Recipe r){return r instanceof ShapedRecipe s&&lodestoneRecipeKey.equals(s.getKey());}
 public ItemStack createCompass(Block b){return createCompass(b,null);}public ItemStack createCompass(Block b,Player p){ItemStack i=new ItemStack(Material.COMPASS);CompassMeta m=(CompassMeta)i.getItemMeta();Location l=b==null?null:b.getLocation();if(l!=null){m.setLodestone(l);m.setLodestoneTracked(true);}String lang=config.language(p);m.getPersistentDataContainer().set(compassKey,PersistentDataType.BYTE,(byte)1);updateVisual(m,lang,l==null?Tracking.UNBOUND:Tracking.TRACKING,l,null);i.setItemMeta(m);return i;}
 public ItemStack createLodestone(Player p){return createLodestone(p,null);}public ItemStack createLodestone(Player p,String label){ItemStack i=new ItemStack(Material.LODESTONE);ItemMeta m=i.getItemMeta();String lang=config.language(p);m.setDisplayName(label==null||label.isBlank()?config.localized(lang,"lodestone-name"):label);m.setLore(List.of(config.localized(lang,"lodestone-lore")));m.getPersistentDataContainer().set(lodestoneKey,PersistentDataType.BYTE,(byte)1);i.setItemMeta(m);return i;}
 public boolean isHardcoreCompass(ItemStack i){return i!=null&&i.getType()==Material.COMPASS&&i.hasItemMeta()&&i.getItemMeta().getPersistentDataContainer().has(compassKey,PersistentDataType.BYTE);}public boolean isTagged(ItemStack i){return isHardcoreCompass(i);}public boolean isHardcoreLodestone(ItemStack i){return i!=null&&i.getType()==Material.LODESTONE&&i.hasItemMeta()&&i.getItemMeta().getPersistentDataContainer().has(lodestoneKey,PersistentDataType.BYTE);}
 public boolean isHardcoreLodestoneBlock(Block b){return b!=null&&b.getType()==Material.LODESTONE&&lodestones.contains(b.getLocation());}
 public void markPlacedLodestone(Block b,UUID owner,String label){lodestones.register(b.getLocation(),owner,label);}
 public String lodestoneLabel(Block b){return lodestones.label(b.getLocation());}
 public boolean mayBreak(Block b,Player p){String mode=config.lodestoneBreakProtection();if(mode.equals("none"))return true;if(mode.equals("admin-only"))return p.hasPermission("hardcorecompass.admin");if(mode.equals("owner-only")){if(p.hasPermission("hardcorecompass.admin"))return true;String id=lodestones.owner(b.getLocation());return id!=null&&id.equals(p.getUniqueId().toString());}return true;}
 public boolean removeLodestone(Block b){return lodestones.unregister(b.getLocation());}
 public boolean tooClose(Location candidate){double minimum=config.lodestoneMinSeparation();if(minimum<=0)return false;double minSquared=minimum*minimum;for(var entry:lodestones.inWorld(candidate.getWorld())){if(entry.x()==candidate.getBlockX()&&entry.y()==candidate.getBlockY()&&entry.z()==candidate.getBlockZ())continue;double dx=(double)entry.x()-candidate.getBlockX(),dz=(double)entry.z()-candidate.getBlockZ();if(dx*dx+dz*dz<minSquared)return true;}return false;}
 public void bind(ItemStack i,Player p,Location l){if(!isHardcoreCompass(i)||!(i.getItemMeta() instanceof CompassMeta m))return;m.setLodestone(l);m.setLodestoneTracked(true);String label=lodestoneLabel(l.getBlock());if(label==null)m.getPersistentDataContainer().remove(targetLabelKey);else m.getPersistentDataContainer().set(targetLabelKey,PersistentDataType.STRING,label);updateVisual(m,config.language(p),Tracking.TRACKING,l,label);i.setItemMeta(m);p.playSound(l,Sound.ITEM_LODESTONE_COMPASS_LOCK,1f,1f);}
 private enum Tracking { TRACKING, UNBOUND, LOST }
 public void markTargetLost(World w,Location loc){for(Player p:Bukkit.getOnlinePlayers()){markContents(p.getInventory().getContents(),p,w,loc);markContents(p.getEnderChest().getContents(),p,w,loc);}}
 private void markContents(ItemStack[] items,Player p,World w,Location target){for(ItemStack i:items){if(!isHardcoreCompass(i)||!(i.getItemMeta() instanceof CompassMeta m)||!m.hasLodestone())continue;Location l=m.getLodestone();if(l==null||l.getWorld()==null||!l.getWorld().equals(w)||l.getBlockX()!=target.getBlockX()||l.getBlockY()!=target.getBlockY()||l.getBlockZ()!=target.getBlockZ())continue;boolean wasTracking=m.isLodestoneTracked();m.setLodestoneTracked(false);updateVisual(m,config.language(p),Tracking.LOST,null,m.getPersistentDataContainer().get(targetLabelKey,PersistentDataType.STRING));i.setItemMeta(m);if(wasTracking){String notice=config.getMessage(p,"compass-target-broken");if(notice==null||notice.isBlank())notice="§6[Hardcore] §cYour bound lodestone has been destroyed!";p.sendMessage(notice);}}}
 public void refreshCompass(ItemStack i,Player p){if(!isHardcoreCompass(i)||!(i.getItemMeta() instanceof CompassMeta m))return;Location target=m.hasLodestone()?m.getLodestone():null;Tracking status=target==null?Tracking.UNBOUND:tracking(target);String label=m.getPersistentDataContainer().get(targetLabelKey,PersistentDataType.STRING);if(status==Tracking.TRACKING&&target!=null){String current=lodestoneLabel(target.getBlock());if(current!=null)label=current;}m.setLodestoneTracked(status==Tracking.TRACKING);updateVisual(m,config.language(p),status,target,label);i.setItemMeta(m);}
 private Tracking tracking(Location l){World w=l.getWorld();if(w==null)return Tracking.LOST;return isHardcoreLodestoneBlock(w.getBlockAt(l))?Tracking.TRACKING:Tracking.LOST;}
 public boolean isTracking(ItemStack i){if(!isHardcoreCompass(i)||!(i.getItemMeta() instanceof CompassMeta m)||!m.hasLodestone())return false;return tracking(m.getLodestone())==Tracking.TRACKING;}
 public void refreshPlayer(Player p){for(ItemStack i:p.getInventory().getContents())refreshCompass(i,p);for(ItemStack i:p.getEnderChest().getContents())refreshCompass(i,p);}
 public void wipeLinks(Player p){for(ItemStack i:p.getInventory().getContents())clearLink(i,p);for(ItemStack i:p.getEnderChest().getContents())clearLink(i,p);}private void clearLink(ItemStack i,Player p){if(!isHardcoreCompass(i)||!(i.getItemMeta() instanceof CompassMeta m))return;m.setLodestone(null);m.setLodestoneTracked(false);m.getPersistentDataContainer().remove(targetLabelKey);updateVisual(m,config.language(p),Tracking.UNBOUND,null,null);i.setItemMeta(m);}
 public ItemStack findTaggedCompass(Player p){for(ItemStack i:p.getInventory().getContents())if(isHardcoreCompass(i))return i.clone();return null;}public void giveStarter(Player p){if(!config.starterEnabled())return;if(config.starterLodestone())p.getInventory().addItem(createLodestone(p));if(config.starterCompass())p.getInventory().addItem(createCompass(null,p));}
 private void updateVisual(CompassMeta m,String lang,Tracking status,Location target,String label){m.setDisplayName(config.localized(lang,"compass-name"));m.setEnchantmentGlintOverride(status==Tracking.TRACKING);String key=status==Tracking.TRACKING?"compass-bound-lore":status==Tracking.UNBOUND?"compass-unbound":"compass-lost";String text=config.localized(lang,key);if(target!=null)text=text.replace("{x}",""+target.getBlockX()).replace("{y}",""+target.getBlockY()).replace("{z}",""+target.getBlockZ());m.setLore(label==null||label.isBlank()?List.of(text):List.of(text,config.localized(lang,"compass-target-label").replace("{label}",label)));}
}
